INSERT INTO SAVED_PASSENGER (
	member_id, name, birth_date, phone, gender, passport_no, passport_expiry
)
SELECT
	#{memberId}, #{name}, #{birthDate,jdbcType=DATE},
	#{phone,jdbcType=VARCHAR}, #{gender,jdbcType=CHAR},
	#{passportNo,jdbcType=VARCHAR}, #{passportExpiry,jdbcType=DATE}
FROM DUAL
WHERE NOT EXISTS (
	SELECT 1 FROM SAVED_PASSENGER sp
	WHERE sp.member_id = #{memberId}
	  AND sp.name = #{name}
	  AND sp.birth_date = #{birthDate,jdbcType=DATE}
)
